package EX18.EX88;
import java.sql.Connection;
import java.sql.Statement;
import java.util.List;

public class Main {
    public static void main(String[] args) throws Exception {
        try (Connection conn = ConnectionFactory.getConnection();
             Statement st = conn.createStatement()) {
            st.execute("CREATE TABLE livros (" +
                    "id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, " +
                    "titulo VARCHAR(200) NOT NULL, " +
                    "autor VARCHAR(120) NOT NULL)");
        }

        LivroDAO dao = new LivroDAOImpl();
        for (int i = 1; i <= 25; i++) {
            dao.salvar(new Livro("Livro " + i, "Autor " + i));
        }

        for (int pagina = 1; pagina <= 3; pagina++) {
            List<Livro> livros = dao.buscarPaginado(pagina, 10);
            System.out.println("Página " + pagina + " (" + livros.size() + " registros):");
            livros.forEach(l -> System.out.println("  " + l));
        }
    }
}
